from pathlib import Path
ROOT=Path.cwd()
MODULE="qseries_v2/oracle_source_network/runtime/sports_checkpoint_gap_recovery.py"
TEST="test_osn_084_sports_checkpoint_after_readback_and_gap_recovery.py"
MODULE_SOURCE='\nfrom dataclasses import dataclass, asdict\nfrom datetime import datetime, timezone, timedelta\nfrom pathlib import Path\nimport json, os, tempfile\n\nSTATE_DIR="qseries_v2/oracle_source_network/state/sports_checkpoints"\nCERT_REL="qseries_v2/oracle_source_network/state/osn084_checkpoint_gap_recovery.json"\n\n@dataclass(frozen=True)\nclass Checkpoint:\n    league:str\n    observation_id:str\n    provider_event_id:str\n    committed_at:str\n    readback_count:int\n    execution_authority:bool=False\n\n@dataclass(frozen=True)\nclass GapWindow:\n    start:str\n    end:str\n\ndef _atomic_write(path,data):\n    path.parent.mkdir(parents=True,exist_ok=True)\n    tmp=path.with_suffix(path.suffix+".tmp")\n    tmp.write_text(json.dumps(data,indent=2),encoding="utf-8")\n    os.replace(tmp,path)\n\ndef checkpoint_after_readback(league,observation_id,provider_event_id,readback_count,root=None):\n    if int(readback_count) < 1:\n        raise RuntimeError("checkpoint rejected: exact PostgreSQL readback must be >= 1")\n    base=Path(root or Path.cwd()).resolve()\n    cp=Checkpoint(\n        league=league,\n        observation_id=str(observation_id),\n        provider_event_id=str(provider_event_id),\n        committed_at=datetime.now(timezone.utc).isoformat(),\n        readback_count=int(readback_count),\n    )\n    path=base/STATE_DIR/f"{league.lower()}.json"\n    _atomic_write(path,asdict(cp))\n    return cp,path\n\ndef plan_gap_windows(last_checkpoint_time,now=None,max_window_minutes=5):\n    if isinstance(last_checkpoint_time,str):\n        last=datetime.fromisoformat(last_checkpoint_time.replace("Z","+00:00"))\n    else:\n        last=last_checkpoint_time\n    now=now or datetime.now(timezone.utc)\n    if last.tzinfo is None: last=last.replace(tzinfo=timezone.utc)\n    if now.tzinfo is None: now=now.replace(tzinfo=timezone.utc)\n    if now <= last:\n        return ()\n    step=timedelta(minutes=max_window_minutes)\n    out=[]\n    cur=last\n    while cur < now:\n        end=min(cur+step,now)\n        out.append(GapWindow(cur.isoformat(),end.isoformat()))\n        cur=end\n    return tuple(out)\n\ndef write_certification(root=None):\n    base=Path(root or Path.cwd()).resolve()\n    now=datetime.now(timezone.utc)\n    windows=plan_gap_windows(now-timedelta(minutes=17),now=now,max_window_minutes=5)\n    state=base/CERT_REL\n    state.write_text(json.dumps({\n        "example_gap_minutes":17,\n        "window_count":len(windows),\n        "windows":[asdict(x) for x in windows],\n        "checkpoint_requires_readback":True,\n        "execution_authority":False,\n    },indent=2),encoding="utf-8")\n    return windows,state\n'
TEST_SOURCE='\nfrom datetime import datetime, timezone, timedelta\nfrom pathlib import Path\nfrom qseries_v2.oracle_source_network.runtime.sports_checkpoint_gap_recovery import (\n    checkpoint_after_readback, plan_gap_windows, write_certification\n)\n\nroot=Path.cwd()\ncp,path=checkpoint_after_readback("NHL","osn084-test-observation","2026020001",1,root=root)\nprint("[CHECKPOINT]",cp)\nassert path.exists()\ntry:\n    checkpoint_after_readback("NHL","bad","bad",0,root=root)\n    raise AssertionError("zero-readback checkpoint should have failed")\nexcept RuntimeError:\n    print("[PASS] zero-readback checkpoint rejected")\n\nnow=datetime.now(timezone.utc)\nwindows=plan_gap_windows(now-timedelta(minutes=17),now=now,max_window_minutes=5)\nassert len(windows)==4\nprint("[GAP_WINDOWS]",windows)\n_,state=write_certification(root=root)\nprint("[STATE]",state)\nprint("[PASS] checkpoint-after-readback enforced")\nprint("[PASS] bounded downtime gap recovery windows certified")\nprint("[PASS] execution_authority=FALSE")\n'
def main():
    print("="*120); print(" OSN-084 SPORTS CHECKPOINT-AFTER-READBACK + GAP RECOVERY INSTALLER"); print("="*120)
    for dep in (
        "qseries_v2/oracle_source_network/state/osn083_restart_idempotency_gate.json",
        "qseries_v2/oracle_source_network/runtime/sports_runtime_scheduler.py",
    ):
        if not (ROOT/dep).exists(): raise SystemExit("[FAIL] missing dependency: "+dep)
        print("[PASS] dependency verified:",dep)
    p=ROOT/MODULE; p.parent.mkdir(parents=True,exist_ok=True); p.write_text(MODULE_SOURCE,encoding="utf-8"); compile(p.read_text(encoding="utf-8"),str(p),"exec")
    t=ROOT/TEST; t.write_text(TEST_SOURCE,encoding="utf-8"); compile(t.read_text(encoding="utf-8"),str(t),"exec")
    print("[WRITE]",MODULE); print("[WRITE]",TEST); print("[PASS] execution_authority=FALSE")
if __name__=="__main__": main()
